// Pedido do NexxusDoc (mesmo formato do fluxo principal): chatInput com o JSON da tarefa.
const input = $input.first().json;
const body = input.body ?? input;
if (typeof body.chatInput !== 'string' || !body.chatInput.trim()) throw new Error('Campo chatInput ausente.');
if (body.chatInput.length > 400000) throw new Error('Pedido grande demais.');
let request;
try { request = JSON.parse(body.chatInput); } catch { throw new Error('chatInput deve conter JSON valido.'); }
const tasks = ['audit_sheet_read', 'audit_evidence_plan'];
if (!tasks.includes(request.task)) throw new Error('Tarefa nao reconhecida no fluxo da Auditoria: ' + request.task);
if (request.task === 'audit_evidence_plan') {
  if (!request.solicitacao || typeof request.solicitacao !== 'object') throw new Error('Solicitacao ausente.');
  // So ids de pasta do Drive (nunca consulta livre); no maximo 6 pastas por roteiro.
  request.pastas_para_listar = (Array.isArray(request.pastas_para_listar) ? request.pastas_para_listar : [])
    .filter(p => p && /^[A-Za-z0-9_-]{15,80}$/.test(String(p.id))).slice(0, 6)
    .map(p => ({ id: String(p.id), nome: String(p.nome || '').slice(0, 120) }));
}
return [{ json: { request, task: request.task } }];

// Planilha mestre (API do Google Sheets) em formato compacto: por aba, linhas de celulas ("texto" ou {v, l} com link).
const r = $input.first().json;
if (!Array.isArray(r.sheets)) throw new Error('A API do Google Sheets nao devolveu as abas da planilha mestre.');
const abas = {};
for (const sh of r.sheets) {
  const titulo = (sh.properties && sh.properties.title) || '';
  const linhas = [];
  for (const d of (sh.data || [])) {
    for (const row of (d.rowData || [])) {
      const cells = (row.values || []).map(c => {
        const v = c.formattedValue == null ? '' : String(c.formattedValue);
        // Link da celula: chip de arquivo/pasta do Drive (como a planilha mestre usa), hiperlink ou link no texto.
        let l = '';
        if (Array.isArray(c.chipRuns)) {
          const chip = c.chipRuns.find(x => x.chip && x.chip.richLinkProperties && x.chip.richLinkProperties.uri);
          if (chip) l = chip.chip.richLinkProperties.uri;
        }
        if (!l && c.hyperlink) l = c.hyperlink;
        if (!l && Array.isArray(c.textFormatRuns)) {
          const run = c.textFormatRuns.find(x => x.format && x.format.link && x.format.link.uri);
          if (run) l = run.format.link.uri;
        }
        if (!/^https:\/\//.test(l)) l = '';  // links internos da planilha (#rangeid) nao interessam
        return l ? { v, l } : v;
      });
      while (cells.length && cells[cells.length - 1] === '') cells.pop();
      linhas.push(cells);
    }
  }
  while (linhas.length && !linhas[linhas.length - 1].length) linhas.pop();
  abas[titulo] = linhas;
}
const texto = JSON.stringify(abas);
let h = 2166136261;
for (let i = 0; i < texto.length; i++) { h ^= texto.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; }
return [{ json: { origem: 'n8n', planilha: r.spreadsheetId || '', titulo: (r.properties && r.properties.title) || '',
  lido_em: new Date().toISOString(), hash: h.toString(16), abas } }];

const req = $('Validar pedido (Auditoria)').first().json.request;
const pastas = req.pastas_para_listar || [];
if (!pastas.length) return [{ json: { id: '', nome: '' } }];
return pastas.map(p => ({ json: { id: p.id, nome: p.nome } }));

// Subpastas do nivel anterior viram a lista do proximo nivel (no maximo 60). Sem subpasta, um item vazio segue a cadeia.
const pastas = $('Acervo: listar nivel 1').all().flatMap(i => Array.isArray(i.json.files) ? i.json.files : [])
  .filter(f => f.mimeType === 'application/vnd.google-apps.folder').slice(0, 60);
return pastas.length ? pastas.map(f => ({ json: { id: f.id, nome: f.name } })) : [{ json: { id: '', nome: '' } }];

// Subpastas do nivel anterior viram a lista do proximo nivel (no maximo 60). Sem subpasta, um item vazio segue a cadeia.
const pastas = $('Acervo: listar nivel 2').all().flatMap(i => Array.isArray(i.json.files) ? i.json.files : [])
  .filter(f => f.mimeType === 'application/vnd.google-apps.folder').slice(0, 60);
return pastas.length ? pastas.map(f => ({ json: { id: f.id, nome: f.name } })) : [{ json: { id: '', nome: '' } }];

// Acervo das pastas listadas: caminho de cada arquivo a partir da pasta inicial, link e data; vai junto do pedido ao agente.
const req = $('Validar pedido (Auditoria)').first().json.request;
const raizes = $('Acervo: pastas iniciais').all().map(i => i.json).filter(p => p.id);
const porId = {};
for (const n of ['Acervo: listar nivel 1', 'Acervo: listar nivel 2', 'Acervo: listar nivel 3']) {
  for (const it of $(n).all()) for (const f of (Array.isArray(it.json.files) ? it.json.files : [])) porId[f.id] = f;
}
for (const r of raizes) if (!porId[r.id]) porId[r.id] = { id: r.id, name: r.nome, raiz: true, parents: [] };
const caminho = f => {
  const partes = []; let atual = f, guarda = 0;
  while (atual && guarda++ < 8) { partes.unshift(atual.name); const p = (atual.parents || [])[0]; atual = p ? porId[p] : null; }
  return partes.join(' / ');
};
const acervo = Object.values(porId).filter(f => !f.raiz).map(f => ({
  id: f.id, nome: f.name, caminho: caminho(f), link: f.webViewLink || '',
  tipo: f.mimeType === 'application/vnd.google-apps.folder' ? 'pasta' : String(f.mimeType || '').split('/').pop().replace('vnd.google-apps.', 'google '),
  modificado: String(f.modifiedTime || '').slice(0, 10) })).slice(0, 500);
return [{ json: { request: { ...req, acervo }, acervo } }];

