// Arquivo do espelho na pasta compartilhada do NexxusDoc (criado vazio pelo administrador).
const files = $input.first().json.files || [];
if (!files.length) throw new Error('Arquivo nexxusdoc_auditoria_planilha.json nao encontrado no Drive. Ele fica na pasta Sua Area > Nexxus > NexxusDoc.');
return [{ json: { id: files[0].id } }];

// Grava quando a planilha mudou ou a ultima gravacao passou de 6 horas (assim o sistema sabe que o espelho automatico esta
// ativo). Solicitacao (Sol#) que ainda nao estava em 'avisadas' = nova: vai no e-mail ao master e a gerencia.
// Primeira leitura (sem 'avisadas' no arquivo): so registra as que ja existem, sem e-mail.
const novo = $('Espelho: normalizar').first().json;
const atual = $input.first().json || {};
const sem = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
const txt = c => (c && typeof c === 'object') ? String(c.v || '') : String(c ?? '');
const lnk = c => (c && typeof c === 'object') ? String(c.l || '') : '';
const aba = (Object.entries(novo.abas || {}).find(([t]) => sem(t).includes('lista de solicita')) || [null, []])[1];
const hi = aba.findIndex(r => Array.isArray(r) && r.filter(c => txt(c).trim()).length >= 3);
const head = hi >= 0 ? aba[hi].map(c => sem(txt(c))) : [];
const col = test => head.findIndex(test);
const C = { id: col(h => h.startsWith('sol#')), controle: col(h => h === 'controle'), solicitacao: col(h => h === 'solicitacao'),
  periodo: col(h => h === 'periodo'), bu: col(h => h === 'bu'), responsavel: col(h => h.includes('responsavel solicitado')),
  pedido: col(h => h.includes('data da solicitacao')), prazo: col(h => h.includes('data prevista')), pasta: col(h => h.includes('pasta para evidencias')) };
const cel = (r, k) => C[k] >= 0 ? r[C[k]] : '';
const linhas = (hi < 0 || C.id < 0) ? [] : aba.slice(hi + 1).filter(r => Array.isArray(r) && /^sol#/i.test(txt(cel(r, 'id')).trim()))
  .map(r => ({ id: txt(cel(r, 'id')).trim(), controle: txt(cel(r, 'controle')), solicitacao: txt(cel(r, 'solicitacao')).slice(0, 1500),
    periodo: txt(cel(r, 'periodo')), bu: txt(cel(r, 'bu')), responsavel: txt(cel(r, 'responsavel')), pedido: txt(cel(r, 'pedido')),
    prazo: txt(cel(r, 'prazo')), pasta: txt(cel(r, 'pasta')), pasta_link: lnk(cel(r, 'pasta')), selecao_link: lnk(cel(r, 'periodo')) }));
const antes = Array.isArray(atual.avisadas) ? atual.avisadas : null;
const novas = antes ? linhas.filter(l => !antes.includes(l.id)).slice(0, 30) : [];
const avisadas = [...new Set([...(antes || []), ...linhas.map(l => l.id)])];
const idade = atual.lido_em ? (Date.now() - Date.parse(atual.lido_em)) / 36e5 : 999;
const mudou = atual.hash !== novo.hash || !(idade < 6) || !antes || novas.length > 0;
return [{ json: { mudou, novas, id: $('Espelho: escolher arquivo').first().json.id, conteudo: JSON.stringify({ ...novo, avisadas }) } }];

// Aviso de solicitacao nova da auditoria (11/11/2026, pedido do usuario): ao master e a gerencia, pelo Gmail como Vektor
// (mesmo formato dos outros e-mails do NexxusDoc). Nada e enviado a auditoria.
const d = $('Espelho: mudou?').first().json;
const PARA = 'admin@example.com, admin@example.com';
const PLANILHA = 'https://docs.google.com/spreadsheets/d/CONFIGURE_ID/edit';
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const a = (href, text) => href ? `<a href="${esc(href)}" style="color:#2e7432">${esc(text || 'abrir')}</a>` : esc(text);
const n = d.novas.length;
const ids = d.novas.map(x => x.id).join(', ');
const subject = (`[NexxusDoc] Auditoria: ${n === 1 ? 'nova solicitação' : n + ' novas solicitações'} · ${ids}`).slice(0, 180);
const td = 'style="border:1px solid #cfdcc0;padding:6px 8px;vertical-align:top"';
const th = 'style="border:1px solid #cfdcc0;padding:6px 8px;background:#dcefc0;text-align:left"';
const linhas = d.novas.map(x => `<tr><td ${td}><b>${esc(x.id)}</b></td><td ${td}>${esc(x.controle)}${x.bu ? '<br>' + esc(x.bu) : ''}</td>
  <td ${td}>${a(x.selecao_link, x.periodo)}</td><td ${td}>${esc(x.solicitacao).replace(/\n/g, '<br>')}</td><td ${td}>${esc(x.responsavel)}</td>
  <td ${td}>${esc(x.pedido)}</td><td ${td}><b>${esc(x.prazo)}</b></td><td ${td}>${a(x.pasta_link, x.pasta || 'Pasta')}</td></tr>`).join('');
const html = `<div style="font-family:Arial,sans-serif;font-size:14px;color:#1f2a24;line-height:1.5">
  <p>Olá,</p><p>A planilha de Controles Internos (Arquivo Geral) recebeu ${n === 1 ? '<b>uma solicitação nova</b>' : '<b>' + n + ' solicitações novas</b>'} da auditoria:</p>
  <table style="border-collapse:collapse;font-size:13px"><thead><tr><th ${th}>Sol.</th><th ${th}>Controle</th><th ${th}>Período</th><th ${th}>O que foi solicitado</th>
  <th ${th}>Responsável</th><th ${th}>Solicitada em</th><th ${th}>Entrega prevista</th><th ${th}>Pasta de evidências</th></tr></thead><tbody>${linhas}</tbody></table>
  <p>${a(PLANILHA, 'Abrir a planilha mestre')}</p>
  <p>No NexxusDoc, a página <b>Auditoria</b> já mostra a solicitação e monta o roteiro de evidências (onde achar cada peça no Drive, no Gmail e no SAP).</p>
  <p style="color:#6b7a72;font-size:12px">Aviso automático do NexxusDoc. Nada foi enviado à auditoria.</p></div>`;
const b64 = s => Buffer.from(String(s), 'utf8').toString('base64');
const mime = [
  'From: Vektor <admin@example.com>', `To: ${PARA}`, `Subject: =?UTF-8?B?${b64(subject)}?=`,
  'MIME-Version: 1.0', 'Content-Type: text/html; charset=UTF-8', 'Content-Transfer-Encoding: base64', '',
  b64(html).replace(/.{76}/g, '$&\r\n'),
].join('\r\n');
const raw = Buffer.from(mime, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
return [{ json: { raw, ids } }];
